insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('voice_audience', 'F', ARRAY['I am writing for an audience','my writing needs to be read and understood by my audience'], ARRAY['I can discuss that I am writing for someone else.','I can discuss the importance of my audience being able to read and understand my writing.'], ARRAY['Audience','read','understood']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('voice_audience', '1', ARRAY['I am writing for a purpose and intended audience.','my writing can engage and influence the reader'], ARRAY['I can describe the audience and purpose of my writing.','I can write with a specific reader or audience in mind.','I can discuss ways I can engage my audience- e.g interesting lead, word choices, persuasive devices etc.'], ARRAY['Audience','purpose','intended','influence','engage']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('voice_audience', '2', ARRAY['I am writing for a purpose and intended audience (express an opinion, explore an idea, narrate)','my writing can engage, speak to and influence the reader','writing can capture a general mood and evoke emotions such as joy, fear, excitement and humour.'], ARRAY['I can explain that an author writes for one of the following purposes: to persuade, to inform, to entertain','I can explain and justify ways I can engage my audience (e.g interesting leads, word choice, onomatopoeia, persuasive devices etc).','I can write with a specific reader or audience in mind.','I can provide information to support reader understanding.','I can experiment with different/new word choices dependent on my audience.'], ARRAY['Purpose','persuade','inform','entertain','engage','explain','influence']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('voice_audience', '3', ARRAY['I am writing for a purpose and intended audience (express an opinion, explore an idea, narrate)','My writing can engage, speak to and influence the reader','Writing can capture a general mood and evoke emotions such as joy, fear, excitement and humour.','Writers have their own voice.'], ARRAY['I can explain that an author writes for one of the following purposes: persuade, inform, entertain','I can explain and justify ways I can engage my audience (e.g interesting leads, word choice, onomatopoeia, persuasive devices etc).','I can write with a specific reader or audience in mind.','I can create an identifiable tone such as compassionate, bittersweet, frustrated or terrified.','I can provide information to support reader understanding.','I can experiment with word choices dependent on my audience.'], ARRAY['Purpose','persuade','inform','entertain','engage','explain','influence']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('voice_audience', '4', ARRAY['writing can be differentiated for the intended audience','formal and informal tone can be used for different audiences and purposes','the importance of engaging my audience','how to imprint my own voice in my writing'], ARRAY['I can use language devices so my writing ''sounds like me''.','I can narrow my focus to engage my reader','I can use a range of strategies to engage my audience (dialogue lead, alliteration, persuasive devices.)','I can identify when to use a formal or informal tone.','I can use different language devices to create a mood or feeling in my writing.'], ARRAY['Intended audience','formal and informal tone','engage','mood']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('voice_audience', '5', ARRAY['writing can be differentiated for the intended audience.','that language/tone varies depending on social contexts and relationships','the importance of engaging my audience','how to imprint my own voice in my writing'], ARRAY['I can use language devices so my writing ''sounds like me''.','I can adapt my language/tone, to suit a range of social contexts.','I can narrow my focus to engage my reader.'], ARRAY['Intended audience','tone','engaging','imprint voice','language devices','language','adapt','Narrow focus']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('voice_audience', '6', ARRAY['the use of language varies depending on the level of formality, social contexts and relationships','what bias is and how writing can be influenced by it','there is a difference between objective and subjective language','topics can be written in different ways for different audiences.','I can write about the same topic for different audiences and purposes','how to imprint my own voice in my writing'], ARRAY['I can use language devices so my writing ''sounds like me''.','I can use bias in my writing for an intended purpose.','I can use objective or subjective language in my writing depending on the purpose.','I can create informative texts for at least 2 different audiences (e.g. Grade 3 class and an academic)'], ARRAY['Audience','purpose','formality','social contexts','bias','objective and subjective']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('word_choice', 'F', ARRAY['writers use familiar words in their writing','writers select words to make their sentences more interesting','words used need to match the topic/text type'], ARRAY['I can match the words to the picture/object.','I can correctly use familiar words in my writing.','I can experiment with new words in my writing.','I can match my vocabulary to the text type I am writing about.','I can experiment with adjectives in my writing','I can use verbs in my writing.','I can experiment with more interesting verbs.','I can experiment with verbs in my writing.'], ARRAY['Familiar words','new vocabulary words','pictures','objects','matching','sense','experiment','verbs','adjectives']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('word_choice', '1', ARRAY['word choices enhance the reader''s experience','word choices allow the writer to communicate a message clearly','different types of words have different purposes','words can be organised into three different tiers ranging from general to specific in meaning.','words, phrases or sentences can be borrowed from other authors.'], ARRAY['I can use tier 2 vocabulary to enhance the reader''s experience and provide clear meaning (eg. frustrated, stumbled).','I can use tier 3 vocabulary to provide a clear message about a specific subject topic (eg. bioluminescence, photosynthesis)','I can use nouns and pronouns to represent people, places and things.','I can use verbs and experiment with adverbs to describe details, including when, where and how.','I can use adjectives to describe the qualities of a noun.','I can use words to describe when and how things happen (prepositions)'], ARRAY['Vocabulary','tier 2','tier 3','striking words','phrases','nouns','pronouns','verbs','adjectives','adverbs','prepositions','describing words']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('word_choice', '2', ARRAY['word choices enhance the reader''s experience','different tiered vocabulary can be used for a specific purpose, ranging from general to specific in meaning','rhymes, rhythm and word patterns can be used to enhance the reader''s experience','the difference between synonyms and antonyms','words, phrases or sentences can be borrowed from other authors'], ARRAY['I can borrow a word, phrase or sentence from another author.','I can identify and use memorable words and phrases.','I can substitute or add descriptive vocabulary to make my writing more interesting.','I can use verbs and adverbs to describe details including when, where and how.','I can experiment with simple figurative language.','I can experiment with alternative vocabulary for common nouns, adjectives and verbs (e.g. other words for said).','I can identify and use tier 3 vocabulary to provide a clear message about a specific subject topic (eg. bioluminescence, photosynthesis)','I can use adjectives to describe the qualities of a noun (characters, settings, emotions, events).'], ARRAY['Vocabulary','tier 2','tier 3','noun','describe','figurative language','substitute','add','verbs','borrow','memorable words and phrases']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('word_choice', '3', ARRAY['word choices are selected and refined, allowing the writer to communicate a message clearly','that a modal verb expresses necessity or possibility e.g can, should, must.','words can have different meanings in different contexts','different tiered vocabulary can be used for a specific purpose, ranging from general to specific in meaning'], ARRAY['I can experiment with figurative language; similes and onomatopoeia, alliteration, metaphors, hyperbole','I can use descriptive words, in the correct context and with creativity.','I can use common and sophisticated connectives.','I can use adverbs in the correct context.','I can use tier 2 vocabulary to enhance the reader''s experience and provide clear meaning (eg. frustrated, stumbled)','I can use tier 3 vocabulary to provide a clear message about a specific subject topic (eg. bioluminescence, photosynthesis)','I can use synonyms for a effect e.g avoid repetition, listening qualities.','I can choose specific words and phrases for a desired effect.'], ARRAY['Tier 3 vocabulary','Descriptive Adjectives','adverbs','Synonyms','Connectives']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('word_choice', '4', ARRAY['specific language can be used for the specific structure of the text (genre)','word choice can help my reader visualise my ideas','words can be organised into three different tiers that can be used at different times for specific purposes','language choices are made depending on formal or informal.','language changes are used for formal and informal purposes.'], ARRAY['I can adjust my language based on whether I am presenting facts or expression an opinion.','I can use a variety of words to influence the mood of my writing.','I can use alliteration to engage my reader.','I can use specific/precise words.','I can use specific words to encourage my reader to visualise.','I can understand how word choice can influence different text types.'], ARRAY['Adjectives','tier words','alliteration','mood','fact and opinion']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('word_choice', '5', ARRAY['vocabulary can be used for greater precision of meaning','words can have different meanings in different contexts','groups of words/phrases can be expanded in a variety of ways','words can be organised into three different tiers that can be used at different times for specific purposes','how to use figurative language effectively.'], ARRAY['I can use precise adjectives/verbs to enhance meaning in my writing.','I can adjust my language based on whether I am presenting facts or expression an opinion.','I can use specific tier 3 technical vocabulary.','I can use figurative language for effect (simile, metaphor, personification).'], ARRAY['Noun group','verb groups','tiered vocabulary','adjectives','precise','figurative language']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('word_choice', '6', ARRAY['vocabulary can be used for greater precision of meaning','words can be organised into three different tiers that can be used at different times for specific purposes','what objective and subjective language is.','how to use figurative language for effect and purpose.'], ARRAY['I can accurately/precisely use verbs and adverbs to enhance meaning in my writing including adverbials of time.','I can make precise verb and adverb choices within my writing.','I can adjust my language based on whether I am presenting facts or expression an opinion. (Objective and subjective language)','I can use figurative language for effect (simile, metaphor, personification).','I can use objective and subjective language for a purpose.'], ARRAY['Tier vocabulary','adverb','precision','figurative language','subjective and objective language']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('ideas', 'F', ARRAY['writing is used to communicate a message/meaning/idea','I need to develop a clear idea before writing (pre-writing)','authors write about their own experience'], ARRAY['I can choose a topic/idea to write about, when given a prompt or starting sentence, drawing upon familiar experiences and topics.','I can convey my own ideas through talking, drawing and writing.','I can use familiar texts to develop my ideas.','I can record my ideas in a graphic organiser.','I can collect ideas/seeds for my writing in my Writer''s Notebook.'], ARRAY['Idea','topic','message','seed','re-read','retell','collect']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('ideas', '1', ARRAY['writing is used to communicate a message/meaning/idea','I need knowledge of my idea/s to include detail in my writing. This knowledge can be developed through mentor texts, experiences'], ARRAY['I can choose a topic/idea to write about, using mentor texts, prompts or my own ideas/experiences.','I can develop an idea/plan through drawings, labelling and vocabulary lists/word banks.','I can include supportive descriptions, details or examples to explain the important ideas in my writing.'], ARRAY['Message','idea','detail','author','topic','vocabulary','description','mentor text','important ideas','writing seeds']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('ideas', '2', ARRAY['ideas are used to convey meaning','how to plan a variety of texts (narrative, informative, persuasive)','how to create ideas for a variety of texts (narrative, informative, persuasive)'], ARRAY['I can elaborate on at least one idea.','I can expand an idea through key details, drawings, labelling and vocabulary lists/word banks.','I can include supportive descriptions, details or examples to explain the important ideas in my writing.'], ARRAY['Audience','structures','topic','ideas','details','descriptions','prior knowledge','personal experience']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('ideas', '3', ARRAY['how to plan a variety of texts in detail (narrative, informative, persuasive)','how to create texts, using characters, settings, plot structures and ideas','ideas and details from mentor texts help when creating written and spoken texts'], ARRAY['I can include multiple ideas in a text from a range of sources.','I can create related ideas that are clear, coherent and in a logical sequence.','I can record my ideas in a range of ways including word splashes, drawings, graphics organisers, mind maps etc.','I can elaborate an idea through interesting details, drawings, labelling and vocabulary lists/word banks to create meaning.'], ARRAY['ideas','audience','mentor texts','sources','range','topic specific']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('ideas', '4', ARRAY['that my ideas affect the choices I make within my writing depending on purpose.','the purpose of refining my ideas','how details support my idea'], ARRAY['I can use a variety of strategies to assist in creating ideas and recording my ideas such as word splashes, drawings, graphics organisers, mind maps etc.','I can generate my ideas from known texts, learnt topics, mentor texts or topics of interest.','I can elaborate on an idea using details.'], ARRAY['specific purpose','generate','elaborate','details','refining']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('ideas', '5', ARRAY['ideas and opinions can be supported by different sources','my ideas can influence the choices I make within my writing depending on purpose.','the purpose of refining my ideas for effect','how relevant details and elaborations support my idea'], ARRAY['I can use a variety of strategies to assist in creating and developing ideas.','I can generate my ideas from known texts, learnt topics, mentor texts or topics of interest.','I can use relevant details to elaborate on an idea.','I can identify and use credible sources to support my ideas.','I can succinctly plan using dot points.','I can expand on my plan to create a piece of writing.'], ARRAY['Credible sources','succinct','expand','purpose','effect']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('ideas', '6', ARRAY['what bias is and how writing can be influenced by it','that my ideas should influence the choices I make within my writing depending on purpose.','how precise details and elaborations support my idea'], ARRAY['I can explain what bias is and what is its purpose in my writing','I can make choices as a writer to enhance my written piece (I can write a narrative to entertain an audience)','I can interpret and paraphrase information from credible sources.','I can expand an idea by using supporting evidence or descriptive language.','I can succinctly plan using dot points.','I can expand on my plan to create piece of writing.'], ARRAY['Bias','objective','subjective','paraphrase','credible source']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('organisation', 'F', ARRAY['writing is directional from left to right and top to bottom','writing is sequenced','writing has features (including a title)'], ARRAY['I can write from left to right, top to bottom.','I can write a title for my writing when needed.','I can include a beginning, middle and end (recount, narrative etc).','I can write in a logical sequence.'], ARRAY['Directionality','spaces','title','logical sequence']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('organisation', '1', ARRAY['writing follows a logical sequence','writing has organisational features and these features assist the reader to understand the message','different text types have unique organisational features based on their purpose'], ARRAY['I can identify organisational features in a text.','I can explain the purpose of organisational features.','I can include organisational features in my writing based on text type/genre.','I can choose a heading that captures the main message of my writing.','I can include basic sequencing and connecting words to organise the events and information in my writing (such as and, then, also, next, last)','I can include beginning, middle, events and ending when writing to entertain.','I can include an introduction and sequence of information when writing to inform.'], ARRAY['Sequence','order','structure','features','genre','purpose','organisation','text type','connecting words','heading/title','beginning','middle','end','problem','solution','introduction','body','quality conclusion']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('organisation', '2', ARRAY['how different types of texts are organised differently','that like ideas can be grouped together.'], ARRAY['I can identify how different language features enhance a text.','I can identify the structure of different text types.','I can reread and edit texts for text structure.','I can include my ideas in a logical sequence.','I can experiment with organising my writing into paragraphs by grouping them into like ideas.','I can include the relevant features of a text type e.g beginning problem, solution, subheading, informative sentence, introduction, conclusion, arguments and reasons.'], ARRAY['Texts','organised','logical sequence','re-read','edit','structure']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('organisation', '3', ARRAY['different text types have different language features and structures to suit purpose.','different text types have different purposes','that paragraphs are used to group like ideas','writer''s can varying pacing in their writing e.g to ''stretch out'' a moment in my writing (spotlight) and when to speed through a moment.'], ARRAY['I can describe how different language features enhance a text.','I can describe the structure of different text types.','I can organise my writing into paragraphs by grouping them into like ideas.','I can elaborate on an idea in each of my paragraphs.','I can include spotlights and speed throughs in my text to highlight key ideas and pace.','I can include clear transitions that connect one sentence to another.'], ARRAY['Text types','language features','organise','describe','enhance','purpose']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('organisation', '4', ARRAY['different text types have different structures to suit the purpose','text connectives are used to sequence and connect ideas','that paragraphs are used to group like ideas'], ARRAY['I can use an appropriate method of planning to suit the text type.','I can select the appropriate text structure to suit the purpose of my writing.','I can identify/explain the organisational features of a range of texts.','I can develop storylines, characters and settings to create a cohesive narrative (narrative only).','I can group ideas together to form paragraphs.','I can use a range of connectives to sequence my ideas (pronouns, adverbials, time connectives).','I can include ''spotlights'' and ''speed throughs'' in my text to highlight key ideas and pace.'], ARRAY['paragraphs','logical','sequence','adverbials']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('organisation', '5', ARRAY['different text types have different structures to suit the purpose','there are a range of devices used to create cohesion in a text','paragraphs are used to enhance the composition of a text'], ARRAY['I can use an appropriate method of planning to suit the text type.','I can select the appropriate text structure to suit the purpose of my writing.','I can identify the organisational features of a range of text types.','I can use with a variety of storylines, characters and settings to create a cohesive narrative (narrative only).','I can explore a range of ways paragraphs can be structured to suit the purpose of the text.','I can use a range of devices to create cohesion within a text. (synonyms, cause and effect, conditionals).','I can include ''spotlights'' and ''speed throughs'' in my text to highlight key ideas and pace.'], ARRAY['Spotlights','speed throughs','purpose','devices','cohesion','organisational features']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('organisation', '6', ARRAY['paragraphs are structured in a specific way and used to enhance the composition of a text','a range of devices can be purposely used to create cohesion in a text'], ARRAY['I can use an appropriate method of planning to suit the text type.','I can purposely structure a paragraph to suit the purpose of my writing.','I can purposely use a range of devices to create cohesion and enhance my text. (transitional phrases, comparison and contrast, word association)'], ARRAY['Paragraph','cohesion','transitional phrases','compare and contrast','word association']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('sentence_fluency', 'F', ARRAY['a simple sentence expresses a single complete idea','sentences are made up of words','sentences need to make sense to the reader'], ARRAY['I can identify the words in my sentence.','I can recognise when I have a complete sentence','I can write a simple sentence that makes sense.','I can identify a noun in a sentence.','I can identify a verb in a sentence.','I can identify an adjective in a sentence.','I can use nouns, verbs and adjectives in a sentence.'], ARRAY['Sentence','nouns','adjectives','sense','verbs','idea']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('sentence_fluency', '1', ARRAY['there are different types of sentences with different features/parts','my sentences need to sound smooth and fluent when I read them aloud.','sentences start in different ways.','there are different tenses to use when writing'], ARRAY['I can experiment with different length sentences for effect.','I can write a simple sentence with a single clause.','I can include a noun/pronoun, verb and object in a simple sentence.','I can use conjunctions to construct a compound sentence (linking 2 independent clauses)','I can experiment with different sentence starters.','I can re-read my sentences to check they sound smooth, fluent and maintain correct tense.'], ARRAY['Clause','simple sentence','compound sentence','smooth','fluent','experiment','noun','pronoun','verb','adjective','tense']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('sentence_fluency', '2', ARRAY['varying the start, structure and length of sentences enhances the reader''s experience','texts are made cohesive by using personal and possessive pronouns and omitting words that can be inferred','a compound sentence is made up of 2 or more independent clauses','a conjunction is used to join clauses within a compound sentence','my sentences need to make sense with consistent tense.'], ARRAY['I can experiment with different length sentences for effect.','I can include compound sentences in my writing.','I can experiment with using complex sentences.','I can use a range of conjunctions to construct a compound sentence (linking 2 independent clauses)','I can re-read my sentences to check they sound smooth, fluent and maintain correct tense.'], ARRAY['conjunctions','compound sentences','fluency','smooth','dependent clause','independent clause','tense']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('sentence_fluency', '3', ARRAY['varying the start, structure and length of sentences enhances the reader''s experience','the structure of a complex sentence','a cohesive piece of writing has appropriate and consistent tense','the fluency of a sentence is impacted by its grammatical structure','in sentences, nouns may be extended into noun groups using articles and adjectives, and verbs may be expressed as verb groups.'], ARRAY['I can compose a complex sentence including an independent and dependent clause/s.','I can use singular and plural verbs effectively.','I can select and maintain an appropriate tense for my writing.','I can start sentences in a variety of ways to engage the reader.','I can re-read and make changes to my writing to ensure that it is fluent and has the correct grammatical structure.'], ARRAY['Sentence structure','cohesion','tense','complex sentence']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('sentence_fluency', '4', ARRAY['varying the start, structure and length of sentences enhances the reader''s experience','the correct structure of a sentence is formed using correct grammar','a cohesive piece of writing has appropriate and consistent tense','different types of sentences are used for a specific purpose','there are 3 types of conjunctions (coordinating, subordinating and correlative)'], ARRAY['I can create a sentence that uses consistent tenses.','I can use both prefixes and suffixes to strengthen and structure my sentences.','I can experiment with my sentence structure to create flow or rhythm.','I can select the appropriate tense to suit purpose.'], ARRAY['Varying structure','conjunctions','coordinating','subordinating','correlative','prefix','suffix']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('sentence_fluency', '5', ARRAY['sentence fluency is the flow of words and phrases within writing and impacts readability','different types of sentences are used for a specific purpose','how to appropriately use different types of conjunctions (coordinating, subordinating and correlative)'], ARRAY['I can use a variety of sentence lengths and types for effect.','I can use connectives to show and build relationships between sentences.','I can use interesting and varied sentence beginnings','I can use a strong starting sentence for a specific purpose.','I can use subsequent sentences to elaborate on the starting sentence.','I can start sentences in a variety of ways to engage the reader.','I can include prepositional phrases in my writing.'], ARRAY['Connectives','sentence types','subsequent','elaborating','readability','correlative']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('sentence_fluency', '6', ARRAY['sentence fluency is the flow of words and phrases within writing and impacts readability','different types of sentences are used for a specific purpose'], ARRAY['I can experiment with sentence structure for maximum impact.','I can embed the use of different sentence types in my writing','I can choose appropriate conjunctions to add precise meaning to sentences'], ARRAY['Readability','impact','purpose','conjunctions','embed']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('conventions', 'F', ARRAY['punctuation makes writing easier for the reader to understand','a capital letter should be used at the start of my writing and for names','writing needs to finish with a full stop','punctuation marks are used to guide the reader through the writing (capital letters and full stops)'], ARRAY['I can start my writing with a capital letter.','I can use lowercase letters correctly.','I can finish my writing with a full stop.','I can explain why I am using certain punctuation in my writing (e.g I am using a full stop to say my writing is finished, I am using a capital letter here because this is someone''s name).','I can work with my teacher to identify if my writing makes sense. (tense)','I can read over my own writing, identifying my capital letters and full stops.','I can work with my teacher to add in any missing capital letters and full stops.'], ARRAY['Punctuation','capital letters','full stops','lowercase','uppercase']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('conventions', '1', ARRAY['the purpose of capital letters within a sentence (at the start and proper nouns)','sentences have concluding punctuation','punctuation can be used to create effect and to guide the reader (exclamation mark, question mark and full stop)'], ARRAY['I can begin my sentences with a capital letter.','I can finish my sentences with a full stop.','I can use a capital letter for a proper noun.','I can use question marks at the end of a sentence when I am writing a question.','I can use exclamation marks for effect.','I can revise my writing to improve meaning and effect.','I edit my writing to fix up punctuation errors.','I can experiment with other types of punctuation (e.g ellipses, quotation marks, commas etc)'], ARRAY['Capital letter','full stop','proper nouns','question mark','beginning','end','revise','edit']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('conventions', '2', ARRAY['capital letters are used for proper nouns (including titles)','commas are used to separate items in lists','texts can be edited and re-read for spelling and sentence boundary punctuation','punctuation can be used to make the text interesting and to support voice','punctuation marks are used to guide the reader through the writing (exclamation marks, question marks, full stops, capital letters, commas)'], ARRAY['I can re-read and edit my text to improve it.','I can include capital letters and full stops in my writing in appropriate places (start and end of a sentence and for proper nouns)','I can ensure capital letters are included when writing a title.','I can include commas appropriately when writing a list.','I can experiment with: apostrophes, ellipses, quotation marks'], ARRAY['Commas','capital letters','proper nouns','pronouns','exclamation marks','question marks']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('conventions', '3', ARRAY['paragraphs are a key organisational features grouping related information together','texts should be re-read and edited for meaning appropriate structure, grammatical choices and punctuation.','apostrophes are used for contractions and to show possession.','punctuation marks are used to guide the reader through the writing (apostrophes, ellipsis)'], ARRAY['I can use paragraphs in my writing.','I can use apostrophes accurately.','I can use ellipsis in my writing.','I can use quotation marks.','I can experiment with using brackets in my writing.','I can edit my writing to ensure conventions are applied consistently and accurately'], ARRAY['Paragraphs','clause','re-read','edit','grammar','apostrophes']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('conventions', '4', ARRAY['that writers use brackets to add additional information','quotation marks are used to symbolise dialogue in my writing','paragraphs are based on one idea or a set of ideas','punctuation marks are used to guide the reader through the writing (quotation marks, apostrophes)'], ARRAY['I can use brackets to clarify the subject within my text.','I can correctly use quotation marks to represent dialog in my text.','I can group relevant ideas into paragraphs'], ARRAY['Brackets','quotation marks','apostrophe','contraction']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('conventions', '5', ARRAY['conventions allow us to edit the text and prepare it for the reader','there are common systems used to edit my writing.','punctuation marks are used to guide the reader through the writing. (commas to indicate phrases)'], ARRAY['I can use commas when using prepositional phrases in my writing.','I can use apostrophes to show possession for regular and irregular nouns.','I can use symbols when editing my writing.','I can use commas to separate dependent and independent clauses.','I can independently edit my writing to improve its readability.','I can explain/justify editing choices for my own writing and when editing others'' writing.'], ARRAY['Punctuation','guide','phrases','possession','irregular','dependent and independent clauses','edit','revise']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('conventions', '6', ARRAY['conventions allow us to edit the text and prepare it for the reader','there are common systems used to edit my writing.','punctuation can be used to guide the reader through the writing and to create effect and experiences'], ARRAY['I can use commas to separate dependent and independent clauses.','I can use colons appropriately in writing.','I can use brackets effectively in my writing.','I can independently edit my writing to improve its readability.','I can use a range of punctuation for different effects and purposes.'], ARRAY['Commas','clauses','dependent','independent','colons','brackets','effects','purposes']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('presentation', 'F', ARRAY['my writing needs to be legible','when I am presenting my work it needs to be my personal best','how to form letters','visuals can enhance my writing','writing can be published for an audience.'], ARRAY['I can draw a picture which matches my writing.','I can form upper and lowercase letters of the alphabet using the correct starting point and direction.','I can form lowercase letters of the alphabet using the correct starting point and direction.','I can include the changes made during revising and editing.'], ARRAY['Audience','letters','publish','pictures/illustrations','author','illustrator','revising and editing']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('presentation', '1', ARRAY['when I present my writing it is for an audience','when I am presenting my work it needs to be my personal best.','when to correctly use upper and lower case letters','I can select different formats to publish','visuals can enhance my writing'], ARRAY['I can include my revisions and edits in my final published piece.','I can select/create visuals that will enhance the reader''s understanding.','I can form upper and lowercase letters of the alphabet using the correct starting point and direction.','I can form lowercase letters of the alphabet using the correct starting point and direction.'], ARRAY['Audience','letters','publish','pictures/illustrations','author','illustrator','revising and editing']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('presentation', '2', ARRAY['how to create and present my writing for an audience','when I am presenting my work it needs to be my personal best','how to write words legibly and with growing fluency','I can experiment with digital options to publish my writing.','visuals can enhance my writing','edits and revisions enhance my work'], ARRAY['I can write words using letters that are correctly formed and legible.','I can use different types of visuals to enhance my presentation with my audience in mind (e.g diagram, pictures, caption)','I can use applications on an iPad to publish my writing.','I can include my revisions and edits in my published work'], ARRAY['Personal best','legibly','uppercase','lowercase','edits','revisions']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('presentation', '3', ARRAY['how to create and present a text for a specific audience','that when I am presenting my work it needs to be my personal best','how to write words using early formed and consistent in size','technology can enhance the presentation of my writing','that a visuals can enhance my writing','that edits and revisions enhance my work.'], ARRAY['I can include appropriate multimodal elements when presenting my writing.','I can produce writing which is legible and easily read by the audience.','I can include my edits and revisions when publishing.','I can include visuals to enhance the understanding and effect of my writing.'], ARRAY['Legible','visuals','effect','edits','revisions']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('presentation', '4', ARRAY['I can present my writing in a range of written and digital formats','what ''white space'' is and how to frame my text appropriately.','visuals can enhance my writing'], ARRAY['I can use clearly formed letters that are an appropriate size.','I can use a range of applications on an iPad to construct, edit and publish a written text.','I can include in my ''white space'' margins, appropriate space between letters, words and lines.','I can include relevant illustrations, labelled diagrams, graphs, charts or tables to enhance my writing.'], ARRAY['White Space','legible','handwritten','applications']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('presentation', '5', ARRAY['I can present my writing in a range of written and digital formats','how to utilise a ''white space'' appropriately to frame my text','visuals can enhance my writing','how to use an agreed upon criteria to revise and edit my own writing and others.'], ARRAY['I can include relevant illustrations, labelled diagrams, graphs, charts or tables to enhance my writing.','I can reread and edit my own and others work using agreed upon criteria.','I can make choices around fonts to create information and formal writing creations.','I can use a range of applications to construct, edit and publish a written text.'], ARRAY['White Space','legible','handwritten','word processing']);
insert into writing_trait_detail (trait_slug, year_level, ku_verbatim, ks_verbatim, vocab) values ('presentation', '6', ARRAY['I can present my writing in a range of written and digital formats','what ''white space'' is and how to frame my text appropriately','visuals can enhance my writing','how to use an agreed upon criteria to revise and edit my own writing and others'], ARRAY['I can make choices around fonts to create information and formal writing creations.','I can develop fluency with my sentences.','I can use a range of applications to construct, edit and publish a written text.','I can include in my ''white space'' margins, appropriate space between letters, words and lines.','I can include relevant illustrations, labelled diagrams, graphs, charts or tables to enhance my writing.'], ARRAY['White Space','legible','handwritten','word processing']);
